import{_ as a,o,c as t,a6 as i}from"./chunks/framework.BIul5s8C.js";const r=JSON.parse('{"title":"python模块","description":"","frontmatter":{},"headers":[],"relativePath":"zh/python/supplement/model.md","filePath":"zh/python/supplement/model.md"}'),n={name:"zh/python/supplement/model.md"};function _(l,e,s,d,p,h){return o(),t("div",null,e[0]||(e[0]=[i('<h1 id="python模块" tabindex="-1">python模块 <a class="header-anchor" href="#python模块" aria-label="Permalink to &quot;python模块&quot;">​</a></h1><h2 id="模块的搜索路径" tabindex="-1">模块的搜索路径 <a class="header-anchor" href="#模块的搜索路径" aria-label="Permalink to &quot;模块的搜索路径&quot;">​</a></h2><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> sys</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(sys.path)	</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 输出模块的所有路径列表</span></span></code></pre></div><h2 id="if-name-main" tabindex="-1"><code>if __name__ == &quot;__main__&quot;</code> <a class="header-anchor" href="#if-name-main" aria-label="Permalink to &quot;`if __name__ == &quot;__main__&quot;`&quot;">​</a></h2><p>每个模块都有<code>__name__</code>属性，用于标识模块的“名称”：</p><ul><li>当模块被导入时，<code>__name__</code>的值是模块名（如math）</li><li>当模块自身被执行时，<code>__name__</code>的值是<code>__main__</code></li></ul><p><strong>核心原理（怎么工作的）</strong></p><ul><li>每个 Python 文件都有一个内置变量 <code>__name__</code>。</li><li>当直接运行这个文件时，Python 会自动把该文件的 <code>__name__</code> 变量设为 <code>&quot;__main__&quot;</code>。</li><li>当在别的文件里导入这个文件时，Python 会把该文件的 <code>__name__</code> 变量设为它的文件名。</li></ul><p>所以，<code>if __name__ == &quot;__main__&quot;:</code> 这行代码就是在问：“我现在是被直接运行的吗？”当你写一个工具类或函数库时，可以在下面写一些调试测试代码。别人 <code>import</code> 你的模块时不会运行这些测试，只有你自己直接运行这个文件时才会执行，互不干扰</p><h2 id="模块的其他属性" tabindex="-1">模块的其他属性 <a class="header-anchor" href="#模块的其他属性" aria-label="Permalink to &quot;模块的其他属性&quot;">​</a></h2><ul><li><p>file属性：每一个模块都有一个内置属性<code>__file__</code>可以查看模块的完整路径</p></li><li><p>all属性：如果一个模块文件中有<code>__all__</code>变量，当使用<code>from xxx import *</code>导入时，只能导入这个列表中的元素</p></li></ul>',11)]))}const m=a(n,[["render",_]]);export{r as __pageData,m as default};
